        cmp(x, y, '#%d' % i)
    if diffs:
        ok = False
        print('--- %d diffs' % len(diffs))
        for p, x, y in diffs[:n]:
            print(p)
            print('   orig:', json.dumps(x, ensure_ascii=False)[:w])
            print('   mine:', json.dumps(y, ensure_ascii=False)[:w])
    if ok and norm(oo) != norm(mo):
        ok = False; print('--- text differs though JSON is equal (formatting/order)')
    print('SAME' if ok else 'DIFF')
main()

