#!/usr/bin/env python3
"""Helpers: run the original on a list of commands; return parsed reply lines."""
import os, subprocess, tempfile, shutil, json
ORIG = os.environ.get('EXE', '/workspace/executable')

def run(cmds, infile=None, save=None, files=(), exe=ORIG, extra=()):
    d = tempfile.mkdtemp(prefix='ro')
    args = [exe, 'run']
    for f in files:
        shutil.copy(f, d)
    if infile:
        shutil.copy(infile, d)
        args.append(os.path.basename(infile))
    script = os.path.join(d, 'cmds.txt')
    with open(script, 'w') as fh:
        for c in cmds:
            fh.write(c.strip() + '\n')
    args += ['--script', 'cmds.txt']
    if save:
        args += ['--save', 'out.bimcraft']
    args += list(extra)
    p = subprocess.run(args, cwd=d, capture_output=True, timeout=600)
    out = []
    for line in p.stdout.decode().split('\n'):
        if not line.strip():
            continue
        try:
            out.append(json.loads(line))
        except Exception:
            out.append(line)
    if save and os.path.exists(os.path.join(d, 'out.bimcraft')):
        shutil.copy(os.path.join(d, 'out.bimcraft'), save)
    shutil.rmtree(d)
    return p.returncode, out, p.stderr.decode()

def c(cmd, **kw):
    return cmd + ' ' + json.dumps(kw)

