//! `inspect` (and so `info x.bimcraft`): the project's levels, element counts, types, families,
//! materials and pictures, view filters and templates, the settings the styles keep, warnings, its
//! name, language, file and undo history.
//!
//! What the project holds by GUID (a layer's material, a template's filters, phase and options…)
//! is shown by name, as the original shows it.

mod families;
mod names;
mod templates;
mod types;
mod warnings;

use crate::json::{Map, Value};
use crate::session::Session;

pub fn inspect(s: &Session) -> Value {
    let pr = &s.project;
    let mut m = Map::new();
    m.insert("counts", counts(pr));
    m.insert("families", families::families(pr));
    m.insert("history", s.history().into());
    m.insert("images", crate::media::material::inspect_images(pr));
    m.insert("language", pr.language().into());
    m.insert("levels", levels(pr));
    m.insert("materials", crate::media::material::inspect_materials(pr));
    m.insert("name", pr.name().into());
    m.insert("path", s.path.clone().into());
    m.insert("types", types::types(pr));
    m.insert("view_filters", templates::view_filters(pr));
    m.insert("view_templates", templates::view_templates(pr));
    m.insert("warnings", Value::Arr(warnings::warnings(pr).into_iter().map(Value::Str).collect()));
    for (k, v) in crate::styles::inspect_entries(s) {
        m.insert(&k, v);
    }
    Value::Obj(m).sorted()
}

/// How many elements of each category the project has.
fn counts(pr: &crate::project::Project) -> Value {
    let mut counts = std::collections::BTreeMap::<String, u64>::new();
    for e in pr.elements.values() {
        let c = e.get("category").and_then(|c| c.as_str()).unwrap_or("").to_string();
        *counts.entry(c).or_insert(0) += 1;
    }
    let mut m = Map::new();
    for (c, n) in counts {
        m.insert(&c, Value::u(n));
    }
    Value::Obj(m)
}

/// The levels, lowest first: each its elevation, id and name.
fn levels(pr: &crate::project::Project) -> Value {
    let levels: Vec<Value> = crate::commands::basic::level_ids_sorted(pr)
        .iter()
        .map(|id| {
            let e = pr.el(*id).unwrap();
            jobj! {"elevation" => e.get("elevation").cloned().unwrap_or(Value::Null), "id" => *id, "name" => e.get("name").cloned().unwrap_or(Value::Null)}
        })
        .collect();
    Value::Arr(levels)
}

/// `elements`, for the callers that still come here: the readers' own.
pub fn elements(s: &Session, p: &Value) -> Result<Value, String> {
    crate::readers::view::cmd_elements(s, p)
}

//! Names of what the project holds by GUID, as `inspect` shows them.

use crate::project::Project;

/// The name of the library entry of this kind a GUID names.
pub fn lib(pr: &Project, kind: &str, g: &str) -> Option<String> {
    let id = pr.lib_find_guid(g)?;
    let e = pr.library.get(&id)?;
    if e.get("kind").and_then(|k| k.as_str()) != Some(kind) {
        return None;
    }
    e.get("name").and_then(|n| n.as_str()).map(|s| s.to_string())
}

/// The name of the library entry a GUID names, whatever its kind.
pub fn any(pr: &Project, g: &str) -> Option<String> {
    pr.lib_name(g)
}

/// A design option's own name (its entry is named `set: option`).
pub fn option(pr: &Project, g: &str) -> Option<String> {
    let full = lib(pr, "design-option", g)?;
    Some(match full.split_once(": ") {
        Some((_, o)) => o.to_string(),
        None => full,
    })
}

//! The types as `inspect` shows them: each category's, as the project holds them, with their
//! layers' and runs' materials by name.

use super::names;
use crate::json::{Map, Value};
use crate::project::Project;

pub fn types(pr: &Project) -> Value {
    let mut out = Map::new();
    let Some(t) = pr.section("types") else {
        return Value::Obj(out);
    };
    for (cat, ts) in t.iter() {
        if cat == "runs" {
            let mut runs = Map::new();
            if let Some(rs) = ts.as_obj() {
                for (rcat, rts) in rs.iter() {
                    runs.insert(rcat, category(pr, rts));
                }
            }
            out.insert(cat, Value::Obj(runs));
        } else {
            out.insert(cat, category(pr, ts));
        }
    }
    Value::Obj(out).sorted()
}

fn category(pr: &Project, ts: &Value) -> Value {
    let mut out = Map::new();
    if let Some(m) = ts.as_obj() {
        for (name, def) in m.iter() {
            out.insert(name, one(pr, def));
        }
    }
    Value::Obj(out)
}

fn material(pr: &Project, v: &mut Value) {
    if let Some(g) = v.get("material").and_then(|m| m.as_str()).map(|s| s.to_string()) {
        if let Some(n) = names::lib(pr, "material", &g) {
            v.set("material", Value::Str(n));
        }
    }
}

fn one(pr: &Project, def: &Value) -> Value {
    let mut d = def.clone();
    material(pr, &mut d);
    if let Some(layers) = d.get_mut("layers").and_then(|l| l.as_arr_mut()) {
        for l in layers.iter_mut() {
            material(pr, l);
        }
    }
    d
}

//! The families as `inspect` lists them: each its category, its connectors (kind and system), its
//! parameters' names and its types' names.

use crate::json::{Map, Value};
use crate::project::Project;

pub fn families(pr: &Project) -> Value {
    let mut out = Map::new();
    let Some(fs) = pr.section("families") else {
        return Value::Obj(out);
    };
    for (name, f) in fs.iter() {
        out.insert(name, one(f));
    }
    Value::Obj(out).sorted()
}

fn one(f: &Value) -> Value {
    let category = f.get("category").cloned().unwrap_or(Value::Null);
    let connectors: Vec<Value> = f
        .get("connectors")
        .and_then(|c| c.as_arr())
        .map(|cs| {
            cs.iter()
                .map(|c| {
                    jobj! {
                        "kind" => c.get("kind").cloned().unwrap_or(Value::Null),
                        "system" => c.get("system").cloned().unwrap_or(Value::Null)
                    }
                })
                .collect()
        })
        .unwrap_or_default();
    let parameters: Vec<Value> = f
        .get("parameters")
        .and_then(|p| p.as_arr())
        .map(|ps| ps.iter().map(|p| p.get("name").cloned().unwrap_or(Value::Null)).collect())
        .unwrap_or_default();
    let mut types: Vec<String> = f.get("types").and_then(|t| t.as_obj()).map(|t| t.keys().cloned().collect()).unwrap_or_default();
    types.sort();
    jobj! {
        "category" => category,
        "connectors" => Value::Arr(connectors),
        "parameters" => Value::Arr(parameters),
        "types" => types
    }
}

//! View filters and view templates as `inspect` shows them: as the project holds them, with what
